<template>
<section class="account-support"><header><p>CUSTOMER SUPPORT</p><h1>고객지원</h1><p>궁금한 점을 확인하고 문의해 주세요.</p></header>
<nav class="as-tabs" aria-label="고객지원 메뉴"><button v-for="t in tabs" :key="t.id" :aria-current="tab===t.id?'page':null" @click="select(t.id)">{{ t.label }}</button><RouterLink v-if="auth.initialized && !auth.isAuthenticated" to="/guest-order">비회원 주문조회</RouterLink></nav>
<p v-if="error" class="as-error" role="alert">{{ error }}</p><p v-if="message" class="as-success" role="status">{{ message }}</p>
<section v-if="tab==='notices'" class="as-card"><h2>공지사항</h2><p v-if="!notices.length && !loading">등록된 공지사항이 없습니다.</p><ul class="as-list"><li v-for="n in notices" :key="n.notice_id"><button class="as-link" @click="openNotice(n.notice_id)">{{ n.is_pinned?'[공지] ':'' }}{{ n.title }}</button><span>{{ date(n.published_at) }}</span><p v-if="notice?.notice_id===n.notice_id" class="as-content">{{ notice.content }}</p></li></ul><div class="as-pagination"><button v-if="noticePage>1" @click="loadNotices(noticePage-1)">이전</button>{{ noticePage }} / {{ noticePages }}<button v-if="noticePage<noticePages" @click="loadNotices(noticePage+1)">다음</button></div></section>
<section v-else-if="tab==='faq'" class="as-card"><h2>자주 묻는 질문</h2><p v-if="!faqs.length && !loading">등록된 질문이 없습니다.</p><details v-for="f in faqs" :key="f.faq_id" class="as-detail"><summary>{{ f.question }}</summary><p class="as-content">{{ f.answer }}</p></details></section>
<section v-else-if="!auth.isAuthenticated" class="as-card"><h2>로그인이 필요합니다</h2><p>1:1 문의와 상담채팅은 회원만 이용할 수 있습니다.</p><RouterLink :to="{name:'login',query:{redirect:'/support'}}">로그인하기 →</RouterLink></section>
<section v-else-if="tab==='qna'" class="as-card"><h2>1:1 문의</h2><form @submit.prevent="submitQuestion"><label>제목<input v-model.trim="question.title" required maxlength="250"></label><label>문의 내용<textarea v-model.trim="question.content" required></textarea></label><button :disabled="busy">문의 등록</button></form><h3>내 문의</h3><p v-if="!questions.length && !loading">등록한 문의가 없습니다.</p><ul class="as-list"><li v-for="q in questions" :key="q.question_id"><button class="as-link" @click="openQuestion(q.question_id)">{{ q.title }}</button><span>{{ q.status }} · {{ date(q.created_at) }}</span><div v-if="selectedQuestion?.question_id===q.question_id"><p class="as-content">{{ selectedQuestion.content }}</p><p v-if="!selectedQuestion.answers.length">답변을 기다리고 있습니다.</p><p v-for="a in selectedQuestion.answers" :key="a.answer_id" class="as-content"><b>답변</b><br>{{ a.content }}</p><button class="as-secondary" @click="deleteQuestion(q.question_id)">문의 삭제</button></div></li></ul><div class="as-pagination"><button v-if="qPage>1" @click="loadQuestions(qPage-1)">이전</button>{{ qPage }} / {{ qPages }}<button v-if="qPage<qPages" @click="loadQuestions(qPage+1)">다음</button></div></section>
<section v-else class="as-card"><h2>상담채팅</h2><form class="as-inline" @submit.prevent="createRoom"><label>상담 제목<input v-model.trim="subject" required maxlength="200"></label><button :disabled="busy">상담 시작</button></form><h3>내 상담</h3><p v-if="!rooms.length && !loading">상담 내역이 없습니다.</p><div class="as-room-list"><button v-for="r in rooms" :key="r.room_id" class="as-secondary" @click="openRoom(r.room_id)">{{ r.subject }} · {{ r.status }}</button></div><div v-if="room" class="as-chat"><h3>{{ room.subject }} · {{ room.status }}</h3><p v-for="m in room.messages" :key="m.message_id" class="as-message"><b>{{ m.sender_type==='USER'?'나':'상담원' }}</b> <small>{{ date(m.created_at) }}</small><br><span class="as-content">{{ m.content }}</span></p><p v-if="!room.messages?.length">메시지를 입력해 상담을 시작하세요.</p><form v-if="room.status!=='CLOSED'" @submit.prevent="sendChat"><label>메시지<textarea v-model.trim="chatText" required maxlength="2000"></textarea></label><button :disabled="busy">전송</button> <button type="button" class="as-secondary" :disabled="busy" @click="closeRoom">상담 종료</button></form><p v-else>종료된 상담입니다.</p></div></section></section>
</template>
<script setup>
import { onMounted,onUnmounted,reactive,ref } from 'vue';
import http from '../../api/http';
import { useAuthStore } from '../../stores/authStore';
const auth=useAuthStore(), tabs=[{id:'notices',label:'공지사항'},{id:'faq',label:'FAQ'},{id:'qna',label:'1:1 문의'},{id:'chat',label:'상담채팅'}];
const tab=ref('notices'),notices=ref([]),faqs=ref([]),questions=ref([]),rooms=ref([]),notice=ref(null),selectedQuestion=ref(null),room=ref(null),subject=ref('1:1 상담'),chatText=ref(''),error=ref(''),message=ref(''),loading=ref(false),busy=ref(false),noticePage=ref(1),noticePages=ref(1),qPage=ref(1),qPages=ref(1),question=reactive({title:'',content:''});
const date=s=>s?new Date(s).toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul'}):'';
function fail(e){error.value=e.userMessage||'요청을 처리하지 못했습니다.'}
async function run(fn,success=''){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn();message.value=success}catch(e){fail(e)}finally{busy.value=false}}
async function loadNotices(page=1){try{const {data}=await http.get('/api/v1/notices',{params:{page,size:10}});notices.value=data.items;noticePage.value=page;noticePages.value=data.meta.total_pages||1;notice.value=null}catch(e){fail(e)}}
async function loadQuestions(page=1){try{const {data}=await http.get('/api/v1/qna',{params:{page,size:10,only_mine:true}});questions.value=data.items;qPage.value=page;qPages.value=data.meta.total_pages||1}catch(e){fail(e)}}
async function loadRooms(){rooms.value=(await http.get('/api/v1/chat/rooms')).data}
async function select(id){tab.value=id;error.value='';message.value='';loading.value=true;try{if(id==='notices')await loadNotices();if(id==='faq')faqs.value=(await http.get('/api/v1/faqs')).data;if(id==='qna'&&auth.isAuthenticated)await loadQuestions();if(id==='chat'&&auth.isAuthenticated)await loadRooms()}catch(e){fail(e)}finally{loading.value=false}}
async function openNotice(id){try{notice.value=(await http.get(`/api/v1/notices/${id}`)).data}catch(e){fail(e)}}
async function openQuestion(id){try{selectedQuestion.value=(await http.get(`/api/v1/qna/${id}`)).data}catch(e){fail(e)}}
function submitQuestion(){run(async()=>{await http.post('/api/v1/qna',{...question,category:'ETC',is_secret:true});question.title='';question.content='';await loadQuestions()},'문의가 등록되었습니다.')}
function deleteQuestion(id){if(!window.confirm('문의를 삭제하시겠습니까?'))return;run(async()=>{await http.delete(`/api/v1/qna/${id}`);selectedQuestion.value=null;await loadQuestions()},'문의를 삭제했습니다.')}
async function openRoom(id){try{room.value=(await http.get(`/api/v1/chat/rooms/${id}`)).data}catch(e){fail(e)}}
function createRoom(){run(async()=>{room.value=(await http.post('/api/v1/chat/rooms',{subject:subject.value})).data;await loadRooms()},'상담방을 열었습니다.')}
function sendChat(){run(async()=>{await http.post(`/api/v1/chat/rooms/${room.value.room_id}/messages`,{content:chatText.value});chatText.value='';await openRoom(room.value.room_id);await loadRooms()})}
function closeRoom(){if(!window.confirm('상담을 종료하시겠습니까?'))return;run(async()=>{await http.post(`/api/v1/chat/rooms/${room.value.room_id}/close`);await openRoom(room.value.room_id);await loadRooms()},'상담이 종료되었습니다.')}
let timer;onMounted(async()=>{if(!auth.initialized)await auth.fetchMe();await select('notices');timer=setInterval(()=>{if(tab.value==='chat'&&room.value&&document.visibilityState==='visible')openRoom(room.value.room_id)},5000)});onUnmounted(()=>clearInterval(timer));
</script>
